import{_ as h,o as i,c as a,a2 as t}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"Worked Examples","description":"","frontmatter":{},"headers":[],"relativePath":"learning/worked-examples.md","filePath":"learning/worked-examples.md"}'),c={name:"learning/worked-examples.md"};function e(o,n,l,r,m,g){return i(),a("div",null,[...n[0]||(n[0]=[t('<h1 id="worked-examples" tabindex="-1">Worked Examples <a class="header-anchor" href="#worked-examples" aria-label="Permalink to &quot;Worked Examples&quot;">​</a></h1><p>Trên trang này# Worked Examples — bài mẫu giải sẵn <a href="#worked-examples-—-bai-mau-giai-san">​</a> Với người mới bắt đầu, xem một lời giải hoàn chỉnh dạy được nhiều hơn là tự vật lộn với bài tương tự. Với người đã thành thục thì ngược lại. Biết learner đang ở đâu quyết định nên cho cái nào.</p><h2 id="van-đe-đau-nguoi-chi-chua-đuoc-vai-thu-mot-luc-​" tabindex="-1">Vấn đề: đầu người chỉ chứa được vài thứ một lúc <a href="#van-đe-đau-nguoi-chi-chua-đuoc-vai-thu-mot-luc">​</a> <a class="header-anchor" href="#van-đe-đau-nguoi-chi-chua-đuoc-vai-thu-mot-luc-​" aria-label="Permalink to &quot;Vấn đề: đầu người chỉ chứa được vài thứ một lúc [​](#van-đe-đau-nguoi-chi-chua-đuoc-vai-thu-mot-luc)&quot;">​</a></h2><p>Trí nhớ làm việc rất hẹp — chỉ giữ được một nhúm thông tin cùng lúc. Khi một learner mới gặp bài toán lạ, đầu con phải cùng lúc gánh: đề nói gì, công thức nào liên quan, mình đang thử hướng nào, bước vừa rồi có đúng không, còn bao nhiêu thời gian. Sức chứa dùng hết vào việc <em>xoay xở</em>, không còn chỗ cho việc <em>hình thành hiểu biết</em>. Learner có thể mò ra đáp án đúng sau 20 phút mà vẫn không rút ra được nguyên tắc nào — vì lúc đó đầu con quá tải để nhận ra nguyên tắc. Worked example gỡ tải đó đi. Lời giải đã có sẵn, nên toàn bộ sức chú ý dồn vào câu hỏi thật sự đáng hỏi: <em>vì sao bước này lại là bước này?</em></p><h2 id="mot-worked-example-tot-khac-mot-loi-giai-đap-an-​" tabindex="-1">Một worked example tốt khác một lời giải đáp án <a href="#mot-worked-example-tot-khac-mot-loi-giai-đap-an">​</a> <a class="header-anchor" href="#mot-worked-example-tot-khac-mot-loi-giai-đap-an-​" aria-label="Permalink to &quot;Một worked example tốt khác một lời giải đáp án [​](#mot-worked-example-tot-khac-mot-loi-giai-đap-an)&quot;">​</a></h2><p>Đáp án cuối sách cho biết <strong>cái gì</strong>. Worked example cho biết <strong>vì sao</strong>. Lời giải thường gặpBước 1: gọi x là… Bước 2: lập phương trình… Bước 3: giải ra x = 4. Vậy đáp án là 4. Worked exampleĐề cho quan hệ giữa hai đại lượng chưa biết → đây là dấu hiệu đặt ẩn. Chọn ẩn là đại lượng xuất hiện nhiều nhất để phương trình gọn nhất. Từ câu &quot;gấp ba lần&quot; ta có… Kiểm lại: thay x = 4 vào điều kiện ban đầu có hợp lý không. Bản thứ hai dạy được <strong>cách quyết định</strong>. Đó mới là thứ chuyển được sang bài sau.</p><h2 id="go-dan-bai-mau-mo-dan-​" tabindex="-1">Gỡ dần: bài mẫu mờ dần <a href="#go-dan-bai-mau-mo-dan">​</a> <a class="header-anchor" href="#go-dan-bai-mau-mo-dan-​" aria-label="Permalink to &quot;Gỡ dần: bài mẫu mờ dần [​](#go-dan-bai-mau-mo-dan)&quot;">​</a></h2><p>Kỹ thuật hiệu quả nhất không phải cho xem bài mẫu rồi bảo làm bài mới, mà <strong>rút dần các bước có sẵn</strong>:</p><ul><li>Bài đầu: giải sẵn toàn bộ, learner đọc và giải thích lại từng bước.</li><li>Bài thứ hai: giải sẵn tới bước áp chót, learner làm nốt bước cuối.</li><li>Bài thứ ba: chỉ cho hai bước đầu, learner làm phần còn lại.</li><li>Bài thứ tư: chỉ cho bước đầu tiên.</li><li>Bài thứ năm: learner làm hoàn toàn một mình. Chuỗi này dịch chuyển learner từ &quot;xem&quot; sang &quot;tự làm&quot; mà không có cú nhảy vực nào. Nemo12 dùng đúng cấu trúc này cho các mảng kiến thức mà learner mới bắt đầu hoặc đã từng thất bại nhiều lần.</li></ul><h2 id="khi-worked-example-thanh-phan-tac-dung-​" tabindex="-1">Khi worked example thành phản tác dụng <a href="#khi-worked-example-thanh-phan-tac-dung">​</a> <a class="header-anchor" href="#khi-worked-example-thanh-phan-tac-dung-​" aria-label="Permalink to &quot;Khi worked example thành phản tác dụng [​](#khi-worked-example-thanh-phan-tac-dung)&quot;">​</a></h2><p>Với learner đã thành thục, xem bài mẫu <strong>kém hiệu quả hơn</strong> tự làm. Con đã có sẵn cấu trúc trong đầu; ngồi xem người khác giải chỉ tốn thời gian và tạo ảo giác hiểu. Ranh giới không nằm ở tuổi hay lớp, mà ở <strong>mảng kiến thức cụ thể</strong>. Một học sinh lớp 9 giỏi đại số vẫn cần worked example khi lần đầu gặp một dạng hình học lạ. Nemo12 quyết định cho ai xem bài mẫu dựa trên mức vững hiện tại ở <strong>chính node kiến thức đó</strong>, không dựa trên đánh giá tổng thể về learner. Điều này giải thích một chuyện lạ trong lớp học Cùng một tiết giảng mẫu, học sinh yếu học được nhiều, học sinh giỏi thấy chán. Cùng một buổi tự làm bài khó, học sinh giỏi tiến bộ, học sinh yếu nản. Không có định dạng nào đúng cho cả lớp — đây là lý do cá nhân hoá không phải chuyện xa xỉ.</p><h2 id="o-nha-​" tabindex="-1">Ở nhà <a href="#o-nha">​</a> <a class="header-anchor" href="#o-nha-​" aria-label="Permalink to &quot;Ở nhà [​](#o-nha)&quot;">​</a></h2><p>Khi con kẹt, thay vì giảng lại, hãy cùng con đọc một lời giải mẫu và hỏi: <em>&quot;Vì sao ở bước này người ta lại làm thế?&quot;</em> Câu hỏi đó biến việc đọc thụ động thành việc học chủ động — và nó cũng cho bạn biết con đang hiểu tới đâu. Với người mới, xem cách làm dạy nhiều hơn tự mò. Với người thạo, tự mò dạy nhiều hơn xem cách làm. <a href="/learning/spaced-practice">Spaced Practice — học giãn cách →</a></p>',13)])])}const p=h(c,[["render",e]]);export{d as __pageData,p as default};
